import{_ as a,o as p,a as n,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/source_operand_transfer_scenario.D9pk9kRZ.png",t="/ascendc.github.io/pr/5487/assets/destination_operand_transfer_scenario.BuMwrD4h.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"数据搬运辅助配置接口","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move_aux_config/data_move_aux_config"},{"text":"SetLoopModePara","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move_aux_config/SetLoopModePara"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move_aux_config/SetLoopModePara.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move_aux_config/SetLoopModePara.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),o={name:"api/SIMD-API/basic_api/memory_vector_compute/data_move_aux_config/SetLoopModePara.md"};function e(i,s,d,r,_,m){return p(),n("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>SetLoopModePara<span id="ZH-CN_TOPIC_0000002414107833"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>DataCopy、DataCopyPad过程中通过该接口使能loop mode并且设置loop mode的参数，在数据搬运结束后通过<a href="ResetLoopModePara.html">ResetLoopModePara</a>重置loop mode的参数。</p><p>具体支持的数据通路为（以<a href="../../aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>Global Memory -&gt; UB <ul><li>GM -&gt; VECIN</li></ul></li><li>UB -&gt; Global Memory <ul><li>VECOUT -&gt; GM</li></ul></li></ul><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetLoopModePara</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LoopModeParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loopParams</span><span class="p">,</span><span class="w"> </span><span class="n">DataCopyMVType</span><span class="w"> </span><span class="n">type</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>loopParams</td><td>输入</td><td>循环模式参数LoopModeParams类型，定义如下，具体参数说明请参考<a href="#table_setloop_2">表2</a>。<br>struct LoopModeParams {<br> loop1Size = 0;<br> loop2Size = 0;<br> loop1SrcStride = 0;<br> loop1DstStride = 0;<br> loop2SrcStride = 0;<br> loop2DstStride = 0 ;<br>};</td></tr><tr><td>type</td><td>输入</td><td>数据搬运模式。DataCopyMVType为枚举类型，定义如下，具体参数说明请参考<a href="#table1166074612214">表3</a>。<br>enum class DataCopyMVType : uint8_t {<br> UB_TO_OUT = 0,<br> OUT_TO_UB = 1,<br>};</td></tr></tbody></table><p><strong>表2</strong> LoopModeParams结构体参数说明<span id="table_setloop_2"></span></p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>loop1Size</td><td>用于设置内层循环的循环次数，数据类型为uint32_t，取值范围为[0, 2^21)。</td></tr><tr><td>loop2Size</td><td>用于设置外层循环的循环次数，数据类型为uint32_t，取值范围为[0, 2^21)。</td></tr><tr><td>loop1SrcStride</td><td>用于设置内层循环中相邻迭代源操作数的数据块间的间隔，单位为字节，数据类型为uint64_t。<br>•当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^21)，并且loop1SrcStride必须32字节对齐。<br>•当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^40)。</td></tr><tr><td>loop1DstStride</td><td>用于设置内层循环中相邻迭代目的操作数的数据块间的间隔，单位为字节，数据类型为uint64_t。<br>•当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^40)。<br>•当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^21)，并且loop1DstStride必须32字节对齐。</td></tr><tr><td>loop2SrcStride</td><td>用于设置外层循环中相邻迭代源操作数的数据块间的间隔，单位为字节，数据类型为uint64_t。<br>•当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^21)，并且loop2SrcStride必须32字节对齐。<br>•当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^40)。</td></tr><tr><td>loop2DstStride</td><td>用于设置外层循环中相邻迭代目的操作数的数据块间的间隔，单位为字节，数据类型为uint64_t。<br>•当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^40)。<br>•当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^21)，并且loop2DstStride必须32字节对齐。</td></tr></tbody></table><p><strong>表3</strong> DataCopyMVType结构体参数说明 <span id="table1166074612214"></span></p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>UB_TO_OUT</td><td>从UB搬运到GM的通路。</td></tr><tr><td>OUT_TO_UB</td><td>从GM搬运到UB的通路。</td></tr></tbody></table><p>下面的样例呈现了SetLoopModePara的使用方法。</p><ul><li>样例中在数据类型为int8_t的场景下，数据块大小为384，配置DataCopyPad的数据搬运模式为Compact模式，blockLen = 48，blockCount = 2，表明每个连续传输数据块包含48字节，且连续传输数据块有两个，srcStride = 0，dstStride = 0，isPad = false，表明源操作数相邻数据块之间没有间隔且不需要填充用户自定义的数据；</li><li>再设置SetLoopModePara中LoopModeParams的参数：loop1Size = 2，loop2Size = 2，loop1SrcStride = 96，loop2SrcStride =192，loop1DstStride = 128，loop2DstStride = 288，DataCopyMVType为OUT_TO_UB，表明内层循环和外层循环的次数分别为2次，内层循环和外层循环中相邻迭代源操作数的数据块间隔分别为96字节和192字节，内层循环和外层循环中相邻迭代目的操作数的数据块间隔分别为128字节和288字节，通路是从GM搬运到Unified Buffer（UB）；</li><li>使用以上配置，调用SetLoopModePara再调用DataCopyPad就可以开启DataCopyPad的loop模式完成数据类型为int8_t的数据块大小为384的数据搬运。详细图解如下：</li></ul><p><strong>图1</strong> 源操作数搬运场景示例<span id="fig6671114911311"></span><br><img src="`+c+'" alt title="源操作数搬运场景示例"></p><p><strong>图2</strong> 目的操作数搬运场景示例<span id="fig226181311513"></span><br><img src="'+t+`" alt title="目的操作数搬运场景示例"></p><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>源操作数和目的操作数的起始地址需要保证32字节对齐。</li><li>目的操作数的数据不能重叠，如果有重叠，硬件层面不会报错或者告警，同时也不能保证重叠数据的正确性；但是不同迭代可以交织，例如内层循环中相邻迭代目的操作数的数据块间的间隔可以小于相邻连续目的操作数的数据块的间隔。</li><li>需要在每次使能loop mode并且设置loop mode的参数后通过ResetLoopModePara进行寄存器的复位，否则会影响到下一次对应通路的搬运的使用，引发异常。</li></ul><h2 id="调用示例">调用示例<span id="section1227835243314"></span><a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>SetLoopModePara使能loop mode，Compact模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 场景4：使用SetLoopModePara使能loop mode进行数据搬运（仅支持Ascend 950PR/Ascend 950DT）。</span>
<span class="c1">// Compact模式：每次内层循环搬运80B后填充16B使其96字节对齐。</span>
<span class="c1">// padding值设为-1。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyExtParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">{</span><span class="n">BLOCK_COUNT</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_LEN</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPadExtParams</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">padParams</span><span class="p">{</span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">-1</span><span class="p">};</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoopModeParams</span><span class="w"> </span><span class="n">loopParam2Ub</span><span class="w"> </span><span class="p">{</span><span class="n">LOOP1_SIZE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP2_SIZE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP1_SRC_STRIDE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP1_DST_STRIDE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP2_SRC_STRIDE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP2_DST_STRIDE</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetLoopModePara</span><span class="p">(</span><span class="n">loopParam2Ub</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyMVType</span><span class="o">::</span><span class="n">OUT_TO_UB</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPad</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PaddingMode</span><span class="o">::</span><span class="n">Compact</span><span class="o">&gt;</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">copyParams</span><span class="p">,</span><span class="w"> </span><span class="n">padParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ResetLoopModePara</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyMVType</span><span class="o">::</span><span class="n">OUT_TO_UB</span><span class="p">);</span>
</code></pre></div></li><li><p>SetLoopModePara使能loop mode，Normal模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 场景5：使用SetLoopModePara使能loop mode进行数据搬运（仅支持Ascend 950PR/Ascend 950DT）。</span>
<span class="c1">// Normal模式：每个block搬运40B后填充24B使其64字节对齐。</span>
<span class="c1">// padding值设为-1。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyExtParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">{</span><span class="n">BLOCK_COUNT</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_LEN</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPadExtParams</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">padParams</span><span class="p">{</span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">-1</span><span class="p">};</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoopModeParams</span><span class="w"> </span><span class="n">loopParam2Ub</span><span class="w"> </span><span class="p">{</span><span class="n">LOOP1_SIZE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP2_SIZE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP1_SRC_STRIDE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP1_DST_STRIDE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP2_SRC_STRIDE</span><span class="p">,</span><span class="w"> </span><span class="n">LOOP2_DST_STRIDE</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetLoopModePara</span><span class="p">(</span><span class="n">loopParam2Ub</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyMVType</span><span class="o">::</span><span class="n">OUT_TO_UB</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPad</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">copyParams</span><span class="p">,</span><span class="w"> </span><span class="n">padParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ResetLoopModePara</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyMVType</span><span class="o">::</span><span class="n">OUT_TO_UB</span><span class="p">);</span>
</code></pre></div></li><li><p>五维数据搬运</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 场景6：五维数据搬运GM[2, 4, 3, 128, 126]int8 -&gt; UB[512, 128]int8。</span>
<span class="c1">// Normal模式，使用loop mode。</span>
<span class="c1">// 搬运规格：[2, 2, 2, 64, 126]，每个126字节补2字节padding到128字节。</span>
<span class="c1">// 最终UB连续存放为[512, 128]。</span>

<span class="c1">// Stride参数说明：</span>
<span class="c1">// - loop1SrcStride=128*126：第2维stride，每次loop1源地址跳过128*126字节</span>
<span class="c1">// - loop1DstStride=64*128：每次loop1目的地址跳过64*128字节（64行×128字节/行）</span>
<span class="c1">// - loop2SrcStride=3*128*126：第1维stride，每次loop2源地址跳过3*128*126字节</span>
<span class="c1">// - loop2DstStride=2*64*128：每次loop2目的地址跳过2*64*128字节</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoopModeParams</span><span class="w"> </span><span class="n">loopParam2Ub</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="mi">2</span><span class="p">,</span><span class="w">  </span><span class="c1">// loop1Size=2（第2维搬运2次）</span>
<span class="w">    </span><span class="mi">2</span><span class="p">,</span><span class="w">  </span><span class="c1">// loop2Size=2（第1维搬运2次）</span>
<span class="w">    </span><span class="mi">128</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">126</span><span class="p">,</span><span class="w">  </span><span class="c1">// loop1SrcStride（第2维stride）</span>
<span class="w">    </span><span class="mi">64</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">128</span><span class="p">,</span><span class="w">   </span><span class="c1">// loop1DstStride</span>
<span class="w">    </span><span class="mi">3</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">128</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">126</span><span class="p">,</span><span class="w">  </span><span class="c1">// loop2SrcStride（第1维stride）</span>
<span class="w">    </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">64</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">128</span><span class="w">    </span><span class="c1">// loop2DstStride</span>
<span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetLoopModePara</span><span class="p">(</span><span class="n">loopParam2Ub</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyMVType</span><span class="o">::</span><span class="n">OUT_TO_UB</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyExtParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">{</span>
<span class="w">    </span><span class="mi">64</span><span class="p">,</span><span class="w">  </span><span class="c1">// blockCount=64（第3维搬运64次）</span>
<span class="w">    </span><span class="mi">126</span><span class="p">,</span><span class="w">  </span><span class="c1">// blockLen=126（第4维搬运126字节，padding到128）</span>
<span class="w">    </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="w">  </span><span class="c1">// srcStride=0, dstStride=0, rsv=0</span>
<span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPadExtParams</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">padParams</span><span class="p">{</span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>

<span class="c1">// 第0维for循环搬运2次。</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dim0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">dim0</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span><span class="w"> </span><span class="n">dim0</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dim0SrcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">3</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">128</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">126</span><span class="p">;</span><span class="w">  </span><span class="c1">// 第0维源stride</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dim0DstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">64</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span><span class="w">   </span><span class="c1">// 第0维目的stride</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dim0</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dim0SrcStride</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dim0</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dim0DstStride</span><span class="p">;</span>

<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPad</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">[</span><span class="n">dstOffset</span><span class="p">],</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">[</span><span class="n">srcOffset</span><span class="p">],</span><span class="w"> </span><span class="n">copyParams</span><span class="p">,</span><span class="w"> </span><span class="n">padParams</span><span class="p">);</span>
<span class="p">}</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">ResetLoopModePara</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyMVType</span><span class="o">::</span><span class="n">OUT_TO_UB</span><span class="p">);</span>
</code></pre></div></li></ul><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/00_data_movement/data_copy_pad_gm2ub_ub2gm">DataCopyPad样例场景4、5、6</a>。</p></article></div>`,1)])])}const S=a(o,[["render",e]]);export{h as __pageData,S as default};
